52	export async function addExpense(
53	  businessId: string,
54	  _prevState: ExpenseState,
55	  formData: FormData,
56	): Promise<ExpenseState> {
57	  const date = formData.get("date") as string;
58	  const category = (formData.get("category") as string)?.trim();
59	  const amountRaw = formData.get("amount") as string;
60	  const note = (formData.get("note") as string)?.trim();
61	
62	  if (!date) {
63	    return { error: "Tanggal wajib diisi." };
64	  }
65	  if (!category) {
66	    return { error: "Kategori wajib diisi." };
67	  }
68	
69	  const amount = Number(amountRaw);
70	  if (!amountRaw || Number.isNaN(amount) || amount <= 0) {
71	    return { error: "Jumlah harus angka lebih dari 0." };
72	  }
73	
74	  const isIngredientPurchase = category === PURCHASE_INGREDIENT_CATEGORY;
75	  const isProductPurchase = category === PURCHASE_PRODUCT_CATEGORY;
76	
77	  const supabase = await createClient();
78	
79	  let ingredientId: string | null = null;
80	  let productId: string | null = null;
81	  let qty: number | null = null;
82	
83	  if (isIngredientPurchase) {
84	    ingredientId = formData.get("ingredientId") as string;
85	    qty = Number(formData.get("qty") as string);
86	    if (!ingredientId) {
87	      return { error: "Pilih bahan yang dibeli." };
88	    }
89	    if (!qty || Number.isNaN(qty) || qty <= 0) {
90	      return { error: "Qty dibeli harus angka lebih dari 0." };
91	    }
92	
93	    const { data: ingredient } = await supabase
94	      .from("ingredients")
95	      .select("id, business_id, stock, unit_cost")
96	      .eq("id", ingredientId)
97	      .single();
98	
99	    if (!ingredient || ingredient.business_id !== businessId) {
100	      return { error: "Bahan baku tidak ditemukan." };
101	    }
102	
103	    const oldValue = Number(ingredient.stock) * Number(ingredient.unit_cost);
104	    const newStock = Number(ingredient.stock) + qty;
105	    const newUnitCost =
106	      newStock > 0 ? Math.round((oldValue + amount) / newStock) : Number(ingredient.unit_cost);
107	
108	    const { error: updateError } = await supabase
109	      .from("ingredients")
110	      .update({ stock: newStock, unit_cost: newUnitCost })
111	      .eq("id", ingredientId);
112	
113	    if (updateError) {
114	      return { error: updateError.message };
115	    }
116	
117	    if (newUnitCost !== Number(ingredient.unit_cost)) {
118	      await supabase.from("ingredient_price_history").insert({
119	        business_id: businessId,
120	        ingredient_id: ingredientId,
121	        unit_cost: newUnitCost,
122	        source: "pembelian",
123	      });
124	      await recalculateProductCostsForIngredient(supabase, ingredientId);
125	    }
126	  }
127	
128	  if (isProductPurchase) {
129	    productId = formData.get("productId") as string;
130	    qty = Number(formData.get("qty") as string);
131	    if (!productId) {
132	      return { error: "Pilih produk yang dibeli." };
133	    }
134	    if (!qty || Number.isNaN(qty) || qty <= 0) {
135	      return { error: "Qty dibeli harus angka lebih dari 0." };
136	    }
137	
138	    const { data: product } = await supabase
139	      .from("products")
140	      .select("id, business_id, stock, cost")
141	      .eq("id", productId)
142	      .single();
143	
144	    if (!product || product.business_id !== businessId) {
145	      return { error: "Produk tidak ditemukan." };
146	    }
147	
148	    const oldValue = Number(product.stock) * Number(product.cost);
149	    const newStock = Number(product.stock) + qty;
150	    const newCost = newStock > 0 ? Math.round((oldValue + amount) / newStock) : Number(product.cost);
151	
152	    const { error: updateError } = await supabase
153	      .from("products")
154	      .update({ stock: newStock, cost: newCost })
155	      .eq("id", productId);
156	
157	    if (updateError) {
158	      return { error: updateError.message };
159	    }
160	  }
161	
162	  const { error } = await supabase.from("expenses").insert({
163	    business_id: businessId,
164	    date,
165	    category,
166	    amount,
167	    note: note || null,
168	    ingredient_id: ingredientId,
169	    product_id: productId,
170	    qty,
171	  });
172	
173	  if (error) {
174	    return { error: error.message };
175	  }
176	
177	  const journalError = await postExpenseJournal(
178	    supabase,
179	    businessId,
180	    date,
181	    category,
182	    amount,
183	    isIngredientPurchase || isProductPurchase,
184	  );
185	
186	  await logActivity(
187	    supabase,
188	    businessId,
189	    "sistem",
190	    journalError ? "warning" : "info",
191	    `Pengeluaran: ${category}`,
192	    journalError
193	      ? `Rp${amount.toLocaleString("id-ID")} — GAGAL posting ke jurnal: ${journalError}`
194	      : `Rp${amount.toLocaleString("id-ID")}${note ? ` · ${note}` : ""}`,
195	  );
196	  revalidatePath(`/business/${businessId}/finance`);
197	  return {
198	    error: journalError
199	      ? `Pengeluaran tersimpan, tapi gagal posting ke jurnal (${journalError}). Tambahkan jurnal koreksi manual di halaman Akuntansi → Jurnal.`
200	      : null,
201	  };
202	}
