204	export async function deleteExpense(businessId: string, expenseId: string) {
205	  const supabase = await createClient();
206	  // Menghapus pengeluaran tidak membalik stok/harga bahan atau produk secara
207	  // otomatis — harga rata-rata tertimbang sudah bercampur dengan pembelian
208	  // lain. Kalau salah input, sesuaikan stok manual di halaman terkait.
209	  const { data: expense } = await supabase
210	    .from("expenses")
211	    .select("category, amount")
212	    .eq("id", expenseId)
213	    .eq("business_id", businessId)
214	    .maybeSingle();
215	  await supabase.from("expenses").delete().eq("id", expenseId).eq("business_id", businessId);
216	  if (expense) {
217	    await logActivity(
218	      supabase,
219	      businessId,
220	      "sistem",
221	      "warning",
222	      `Pengeluaran dihapus: ${expense.category}`,
223	      `Rp${Number(expense.amount).toLocaleString("id-ID")}`,
224	    );
225	  }
226	  revalidatePath(`/business/${businessId}/finance`);
227	}
