242	export async function addReconciliation(
243	  businessId: string,
244	  _prevState: ReconciliationState,
245	  formData: FormData,
246	): Promise<ReconciliationState> {
247	  const date = formData.get("date") as string;
248	  const method = (formData.get("method") as string)?.trim();
249	  const amountRaw = formData.get("amount") as string;
250	  const note = (formData.get("note") as string)?.trim();
251	
252	  if (!date) {
253	    return { error: "Tanggal wajib diisi." };
254	  }
255	  if (!method) {
256	    return { error: "Pilih metode pembayaran." };
257	  }
258	
259	  const amount = Number(amountRaw);
260	  if (!amountRaw || Number.isNaN(amount) || amount <= 0) {
261	    return { error: "Jumlah harus angka lebih dari 0." };
262	  }
263	
264	  const supabase = await createClient();
265	
266	  const { data: openShift } = await supabase
267	    .from("shifts")
268	    .select("id")
269	    .eq("business_id", businessId)
270	    .is("closed_at", null)
271	    .limit(1)
272	    .maybeSingle();
273	
274	  if (openShift) {
275	    return { error: "Tutup shift dulu sebelum mencatat rekonsiliasi." };
276	  }
277	
278	  const { error } = await supabase.from("reconciliations").insert({
279	    business_id: businessId,
280	    date,
281	    method,
282	    actual_amount: amount,
283	    note: note || null,
284	  });
285	
286	  if (error) {
287	    return { error: error.message };
288	  }
289	
290	  revalidatePath(`/business/${businessId}/finance`);
291	  return { error: null };
292	}
