13	async function postPurchaseJournal(
14	  supabase: SupabaseServerClient,
15	  businessId: string,
16	  date: string,
17	  description: string,
18	  amount: number,
19	  paidAmount: number,
20	): Promise<string | null> {
21	  const lines: { account_code: string; debit: number; credit: number }[] = [
22	    { account_code: "1-200", debit: amount, credit: 0 },
23	  ];
24	  if (paidAmount > 0) {
25	    lines.push({ account_code: "1-001", debit: 0, credit: paidAmount });
26	  }
27	  const sisaUtang = amount - paidAmount;
28	  if (sisaUtang > 0) {
29	    lines.push({ account_code: "2-001", debit: 0, credit: sisaUtang });
30	  }
31	  const { error } = await supabase.rpc("post_journal_entry", {
32	    p_business_id: businessId,
33	    p_date: date,
34	    p_description: description,
35	    p_lines: lines,
36	  });
37	  return error?.message ?? null;
38	}
