42	export async function addPurchase(
43	  businessId: string,
44	  prevState: AddPurchaseState,
45	  formData: FormData,
46	): Promise<AddPurchaseState> {
47	  const fail = (msg: string): AddPurchaseState => ({ error: msg, resetToken: prevState.resetToken });
48	
49	  const supplierId = (formData.get("supplierId") as string) || null;
50	  const date = formData.get("date") as string;
51	  const dueDate = (formData.get("dueDate") as string) || null;
52	  const category = formData.get("category") as string;
53	  const note = (formData.get("note") as string)?.trim();
54	  const amountRaw = formData.get("amount") as string;
55	  const paidAmountRaw = formData.get("paidAmount") as string;
56	  const qtyRaw = formData.get("qty") as string;
57	
58	  if (!date) {
59	    return fail("Tanggal wajib diisi.");
60	  }
61	  if (category !== "Bahan Baku" && category !== "Barang Dagang") {
62	    return fail("Kategori tidak valid.");
63	  }
64	
65	  const amount = Number(amountRaw);
66	  if (!amountRaw || Number.isNaN(amount) || amount <= 0) {
67	    return fail("Total pembelian harus angka lebih dari 0.");
68	  }
69	
70	  const paidAmount = paidAmountRaw ? Number(paidAmountRaw) : 0;
71	  if (Number.isNaN(paidAmount) || paidAmount < 0) {
72	    return fail("Jumlah dibayar harus angka dan tidak boleh negatif.");
73	  }
74	  if (paidAmount > amount) {
75	    return fail("Jumlah dibayar tidak boleh lebih besar dari total pembelian.");
76	  }
77	
78	  const qty = Number(qtyRaw);
79	  if (!qtyRaw || Number.isNaN(qty) || qty <= 0) {
80	    return fail("Qty dibeli harus angka lebih dari 0.");
81	  }
82	
83	  const supabase = await createClient();
84	
85	  let ingredientId: string | null = null;
86	  let productId: string | null = null;
87	  let itemName = "";
88	
89	  if (category === "Bahan Baku") {
90	    ingredientId = formData.get("ingredientId") as string;
91	    if (!ingredientId) {
92	      return fail("Pilih bahan yang dibeli.");
93	    }
94	
95	    const { data: ingredient } = await supabase
96	      .from("ingredients")
97	      .select("id, name, business_id, stock, unit_cost")
98	      .eq("id", ingredientId)
99	      .single();
100	
101	    if (!ingredient || ingredient.business_id !== businessId) {
102	      return fail("Bahan baku tidak ditemukan.");
103	    }
104	    itemName = ingredient.name;
105	
106	    const oldValue = Number(ingredient.stock) * Number(ingredient.unit_cost);
107	    const newStock = Number(ingredient.stock) + qty;
108	    const newUnitCost =
109	      newStock > 0 ? Math.round((oldValue + amount) / newStock) : Number(ingredient.unit_cost);
110	
111	    const { error: updateError } = await supabase
112	      .from("ingredients")
113	      .update({ stock: newStock, unit_cost: newUnitCost })
114	      .eq("id", ingredientId);
115	
116	    if (updateError) {
117	      return fail(updateError.message);
118	    }
119	
120	    if (newUnitCost !== Number(ingredient.unit_cost)) {
121	      await supabase.from("ingredient_price_history").insert({
122	        business_id: businessId,
123	        ingredient_id: ingredientId,
124	        unit_cost: newUnitCost,
125	        source: "pembelian",
126	      });
127	      await recalculateProductCostsForIngredient(supabase, ingredientId);
128	    }
129	  } else {
130	    productId = formData.get("productId") as string;
131	    if (!productId) {
132	      return fail("Pilih produk yang dibeli.");
133	    }
134	
135	    const { data: product } = await supabase
136	      .from("products")
137	      .select("id, name, business_id, stock, cost")
138	      .eq("id", productId)
139	      .single();
140	
141	    if (!product || product.business_id !== businessId) {
142	      return fail("Produk tidak ditemukan.");
143	    }
144	    itemName = product.name;
145	
146	    const oldValue = Number(product.stock) * Number(product.cost);
147	    const newStock = Number(product.stock) + qty;
148	    const newCost = newStock > 0 ? Math.round((oldValue + amount) / newStock) : Number(product.cost);
149	
150	    const { error: updateError } = await supabase
151	      .from("products")
152	      .update({ stock: newStock, cost: newCost })
153	      .eq("id", productId);
154	
155	    if (updateError) {
156	      return fail(updateError.message);
157	    }
158	  }
159	
160	  const { error } = await supabase.from("purchases").insert({
161	    business_id: businessId,
162	    supplier_id: supplierId,
163	    date,
164	    due_date: dueDate,
165	    category,
166	    ingredient_id: ingredientId,
167	    product_id: productId,
168	    qty,
169	    note: note || null,
170	    amount,
171	    paid_amount: paidAmount,
172	  });
173	
174	  if (error) {
175	    return fail(error.message);
176	  }
177	
178	  const journalError = await postPurchaseJournal(
179	    supabase,
180	    businessId,
181	    date,
182	    `Pembelian: ${itemName}`,
183	    amount,
184	    paidAmount,
185	  );
186	
187	  await logActivity(
188	    supabase,
189	    businessId,
190	    "produk",
191	    journalError ? "warning" : "sukses",
192	    `Pembelian: ${itemName}`,
193	    journalError
194	      ? `Rp${amount.toLocaleString("id-ID")} — GAGAL posting ke jurnal: ${journalError}`
195	      : `Rp${amount.toLocaleString("id-ID")}${paidAmount < amount ? " · sebagian/seluruhnya utang" : " · lunas"}`,
196	  );
197	
198	  revalidatePath(`/business/${businessId}/purchases`);
199	  revalidatePath(`/business/${businessId}/suppliers`);
200	  return journalError
201	    ? fail(
