210	  businessId: string,
211	  purchaseId: string,
212	  _prevState: AddPaymentState,
213	  formData: FormData,
214	): Promise<AddPaymentState> {
215	  const date = formData.get("date") as string;
216	  const amountRaw = formData.get("amount") as string;
217	  const note = (formData.get("note") as string)?.trim();
218	
219	  if (!date) {
220	    return { error: "Tanggal wajib diisi." };
221	  }
222	
223	  const amount = Number(amountRaw);
224	  if (!amountRaw || Number.isNaN(amount) || amount <= 0) {
225	    return { error: "Jumlah bayar harus angka lebih dari 0." };
226	  }
227	
228	  const supabase = await createClient();
229	
230	  const { data: purchase } = await supabase
231	    .from("purchases")
232	    .select("id, business_id, amount, paid_amount, ingredient_id, product_id")
233	    .eq("id", purchaseId)
234	    .eq("business_id", businessId)
235	    .single();
236	
237	  if (!purchase) {
238	    return { error: "Data pembelian tidak ditemukan." };
239	  }
240	
241	  const sisaUtang = Number(purchase.amount) - Number(purchase.paid_amount);
242	  if (amount > sisaUtang) {
243	    return { error: `Jumlah bayar melebihi sisa utang (${sisaUtang.toLocaleString("id-ID")}).` };
244	  }
245	
246	  const newPaidAmount = Number(purchase.paid_amount) + amount;
247	
248	  const { error: updateError } = await supabase
249	    .from("purchases")
250	    .update({ paid_amount: newPaidAmount })
251	    .eq("id", purchaseId);
252	
253	  if (updateError) {
254	    return { error: updateError.message };
255	  }
256	
257	  const { error } = await supabase.from("purchase_payments").insert({
258	    business_id: businessId,
259	    purchase_id: purchaseId,
260	    date,
261	    amount,
262	    note: note || null,
263	  });
264	
265	  if (error) {
266	    return { error: error.message };
267	  }
268	
269	  const { error: journalRpcError } = await supabase.rpc("post_journal_entry", {
270	    p_business_id: businessId,
271	    p_date: date,
272	    p_description: "Bayar utang dagang",
273	    p_lines: [
274	      { account_code: "2-001", debit: amount, credit: 0 },
275	      { account_code: "1-001", debit: 0, credit: amount },
276	    ],
277	  });
278	  const journalError = journalRpcError?.message ?? null;
279	
280	  await logActivity(
281	    supabase,
282	    businessId,
283	    "sistem",
284	    journalError ? "warning" : "info",
285	    "Bayar utang dagang",
286	    journalError
287	      ? `Rp${amount.toLocaleString("id-ID")} — GAGAL posting ke jurnal: ${journalError}`
288	      : `Rp${amount.toLocaleString("id-ID")}${note ? ` · ${note}` : ""}`,
289	  );
290	
291	  revalidatePath(`/business/${businessId}/purchases`);
292	  revalidatePath(`/business/${businessId}/suppliers`);
293	  return {
294	    error: journalError
295	      ? `Pembayaran tersimpan, tapi gagal posting ke jurnal (${journalError}). Tambahkan jurnal koreksi manual di halaman Akuntansi → Jurnal.`
296	      : null,
297	  };
298	}
