25	function agingBucketOf(dateStr: string, todayIso: string): AgingBucket {
26	  const days = Math.floor(
27	    (new Date(`${todayIso}T00:00:00Z`).getTime() - new Date(`${dateStr}T00:00:00Z`).getTime()) /
28	      86400000,
29	  );
30	  if (days <= 30) return "0-30 hari";
31	  if (days <= 60) return "31-60 hari";
32	  if (days <= 90) return "61-90 hari";
33	  return "90+ hari";
34	}
