146	export async function adjustIngredientStock(
147	  businessId: string,
148	  ingredientId: string,
149	  newStock: number,
150	  reason: string,
151	): Promise<AdjustStockResult> {
152	  if (Number.isNaN(newStock) || newStock < 0) {
153	    return { error: "Stok fisik harus angka dan tidak boleh negatif." };
154	  }
155	  reason = reason.trim();
156	  if (!reason) {
157	    return { error: "Alasan penyesuaian wajib diisi." };
158	  }
159	
160	  const supabase = await createClient();
161	
162	  const { data: ingredient } = await supabase
163	    .from("ingredients")
164	    .select("id, name, unit, stock")
165	    .eq("id", ingredientId)
166	    .eq("business_id", businessId)
167	    .single();
168	
169	  if (!ingredient) {
170	    return { error: "Bahan baku tidak ditemukan." };
171	  }
172	
173	  const stockBefore = Number(ingredient.stock);
174	  const diff = newStock - stockBefore;
175	
176	  if (diff === 0) {
177	    return { error: "Stok fisik sama dengan stok sistem, tidak ada yang disesuaikan." };
178	  }
179	
180	  const { error: updateError } = await supabase
181	    .from("ingredients")
182	    .update({ stock: newStock })
183	    .eq("id", ingredientId);
184	
185	  if (updateError) {
186	    return { error: updateError.message };
187	  }
188	
189	  await supabase.from("stock_adjustments").insert({
190	    business_id: businessId,
191	    ingredient_id: ingredientId,
192	    item_name: ingredient.name,
193	    unit: ingredient.unit,
194	    stock_before: stockBefore,
195	    stock_after: newStock,
196	    diff,
197	    reason,
198	  });
199	
200	  await logActivity(
201	    supabase,
202	    businessId,
203	    "produk",
204	    "warning",
205	    `Penyesuaian stok: ${ingredient.name}`,
206	    `${stockBefore} → ${newStock} ${ingredient.unit} (${diff > 0 ? "+" : ""}${diff}) · ${reason}`,
207	  );
208	  revalidatePath(`/business/${businessId}/ingredients`);
209	  return { error: null };
210	}
