68	export async function checkout(
69	  businessId: string,
70	  cashierId: string,
71	  items: CartItemInput[],
72	  paymentMethod: string,
73	  received: number | null,
74	  orderDisc: number,
75	  orderDiscType: DiscountType,
76	  customerId: string | null = null,
77	  selfOrderIds: string[] = [],
78	  // Dibuat sekali di browser per penjualan (crypto.randomUUID()) dan dikirim
79	  // ulang apa adanya kalau ini retry dari antrian offline — RPC memakainya
80	  // untuk mengenali retry yang mengulang penjualan yang sebenarnya sudah
81	  // sukses (respons sebelumnya tidak sempat sampai ke browser), supaya tidak
82	  // membuat transaksi duplikat. Lihat src/hooks/use-offline-sync.ts.
83	  clientRef: string | null = null,
84	): Promise<CheckoutResult> {
85	  if (items.length === 0) {
86	    return { success: false, error: "Keranjang masih kosong." };
87	  }
88	
89	  const supabase = await createClient();
90	  const { data, error } = await supabase
91	    .rpc("checkout_transaction", {
92	      p_business_id: businessId,
93	      p_cashier_id: cashierId,
94	      p_items: items.map((i) => ({
95	        product_id: i.productId,
96	        qty: i.qty,
97	        disc: i.disc,
98	        disc_type: i.discType,
99	      })),
100	      p_payment_method: paymentMethod,
101	      p_received: received,
102	      p_order_disc: orderDisc,
103	      p_order_disc_type: orderDiscType,
104	      p_customer_id: customerId,
105	      p_self_order_ids: selfOrderIds.length > 0 ? selfOrderIds : null,
106	      p_client_ref: clientRef,
107	    })
108	    .single();
109	
110	  if (error || !data) {
111	    return { success: false, error: error?.message ?? "Gagal memproses transaksi." };
112	  }
113	
114	  const result = data as CheckoutRpcRow;
115	
116	  // Retry offline yang ternyata sudah pernah sukses sebelumnya — jangan catat
117	  // aktivitas/cetak dapur dua kali untuk penjualan yang sama.
118	  if (!result.already_existed) {
119	    const itemCount = items.reduce((sum, i) => sum + i.qty, 0);
120	    await logActivity(
121	      supabase,
122	      businessId,
123	      "transaksi",
124	      "sukses",
125	      `Transaksi ${result.invoice_number}`,
126	      `${itemCount} item · ${paymentMethod}`,
127	    );
128	
129	    await printKitchenTicketsForItems(
130	      supabase,
131	      businessId,
132	      "Kasir",
133	      result.invoice_number,
134	      items.map((i) => ({ productId: i.productId, qty: i.qty })),
135	    );
136	  }
137	
138	  return { success: true, invoiceNumber: result.invoice_number, transactionId: result.transaction_id };
139	}
