231	  const { data, error } = await supabase
232	    .rpc("close_shift", {
233	      p_shift_id: shiftId,
234	      p_closing_cash: closingCash,
235	      p_close_notes: closeNotes || null,
236	    })
237	    .single();
238	
239	  if (error || !data) {
240	    return { success: false, error: error?.message ?? "Gagal menutup shift." };
241	  }
242	
243	  const summary = data as CloseShiftSummary;
244	  await logActivity(
245	    supabase,
246	    businessId,
247	    "sistem",
248	    summary.difference === 0 ? "info" : "warning",
249	    "Shift ditutup",
250	    `Penjualan Rp${summary.total_sales.toLocaleString("id-ID")} · ${summary.tx_count} transaksi · selisih Rp${summary.difference.toLocaleString("id-ID")}`,
251	  );
252	  return { success: true, summary };
253	}
