268	export async function saveOpenBill(
269	  businessId: string,
270	  billId: string | null,
271	  label: string,
272	  items: OpenBillItemInput[],
273	): Promise<SaveOpenBillResult> {
274	  const trimmed = label.trim();
275	  if (!trimmed) {
276	    return { success: false, error: "Nama bon wajib diisi." };
277	  }
278	  if (items.length === 0) {
279	    return { success: false, error: "Keranjang masih kosong." };
280	  }
281	
282	  const supabase = await createClient();
283	
284	  if (billId) {
285	    const { error } = await supabase
286	      .from("open_bills")
287	      .update({ label: trimmed, items, updated_at: new Date().toISOString() })
288	      .eq("id", billId)
289	      .eq("business_id", businessId);
290	    if (error) {
291	      return { success: false, error: error.message };
292	    }
293	    revalidatePath(`/business/${businessId}/pos`);
294	    return { success: true, billId };
295	  }
296	
297	  const { data, error } = await supabase
298	    .from("open_bills")
299	    .insert({ business_id: businessId, label: trimmed, items })
300	    .select("id")
301	    .single();
302	
303	  if (error || !data) {
304	    return { success: false, error: error?.message ?? "Gagal menyimpan bon." };
305	  }
306	
307	  await logActivity(
308	    supabase,
309	    businessId,
310	    "transaksi",
311	    "info",
312	    `Open Bill dibuat: ${trimmed}`,
313	    `${items.length} jenis item`,
314	  );
315	  revalidatePath(`/business/${businessId}/pos`);
316	  return { success: true, billId: data.id };
317	}
