325	export async function updateSelfOrderStatus(
326	  businessId: string,
327	  orderId: string,
328	  status: "diproses" | "selesai",
329	): Promise<{ success: boolean; error?: string }> {
330	  const supabase = await createClient();
331	  const { data, error } = await supabase
332	    .from("self_orders")
333	    .update({ status })
334	    .eq("id", orderId)
335	    .eq("business_id", businessId)
336	    .select("tables(name)")
337	    .single();
338	
339	  if (error) {
340	    return { success: false, error: error.message };
341	  }
342	
343	  const tableName =
344	    (data as unknown as { tables: { name: string } | null }).tables?.name ?? "Meja terhapus";
345	  await logActivity(
346	    supabase,
347	    businessId,
348	    "transaksi",
349	    "info",
350	    `Pesanan ${tableName} → ${status}`,
351	  );
352	
353	  if (status === "diproses") {
354	    const { data: orderItems } = await supabase
355	      .from("self_order_items")
356	      .select("product_id, name, qty, note, products(category)")
357	      .eq("self_order_id", orderId);
358	
359	    if (orderItems && orderItems.length > 0) {
360	      const failures = await dispatchKitchenPrint(supabase, businessId, {
361	        source: tableName,
362	        label: "Pesanan Self-Order",
363	        items: orderItems.map((i) => ({
364	          name: i.name,
365	          category: (i as unknown as { products: { category: string | null } | null }).products
366	            ?.category ?? null,
367	          qty: Number(i.qty),
368	          note: i.note,
369	        })),
370	      }).catch(() => []);
371	
372	      const failed = failures.filter((f) => !f.ok);
373	      if (failed.length > 0) {
374	        await logActivity(
375	          supabase,
376	          businessId,
377	          "sistem",
378	          "warning",
379	          `Gagal cetak ke dapur: ${failed.map((f) => f.printer).join(", ")}`,
380	          failed.map((f) => f.error).join(" · "),
381	        );
382	      }
383	    }
384	  }
385	
386	  revalidatePath(`/business/${businessId}/pos`);
387	  revalidatePath(`/business/${businessId}/tables`);
388	  return { success: true };
389	}
