20	drop function if exists public.checkout_transaction(
21	  uuid, uuid, jsonb, text, numeric, numeric, text, uuid, uuid[]
22	);
23	
24	create or replace function public.checkout_transaction(
25	  p_business_id uuid,
26	  p_cashier_id uuid,
27	  p_items jsonb, -- array of {product_id, qty, disc, disc_type}
28	  p_payment_method text,
29	  p_received numeric default null,
30	  p_order_disc numeric default 0,
31	  p_order_disc_type text default 'pct',
32	  p_customer_id uuid default null,
33	  p_self_order_ids uuid[] default null,
34	  p_client_ref uuid default null
35	)
36	returns table (transaction_id uuid, invoice_number text, already_existed boolean)
37	language plpgsql
38	security definer
39	set search_path = ''
40	as $$
41	declare
42	  v_business record;
43	  v_invoice_number text;
44	  v_seq int;
45	  v_subtotal_raw numeric(12, 2) := 0;
46	  v_total_item_disc numeric(12, 2) := 0;
47	  v_order_disc_amt numeric(12, 2) := 0;
48	  v_subtotal numeric(12, 2);
49	  v_service numeric(12, 2) := 0;
50	  v_tax numeric(12, 2) := 0;
51	  v_total numeric(12, 2);
52	  v_total_cost numeric(12, 2) := 0;
53	  v_transaction_id uuid;
54	  v_item jsonb;
55	  v_qty numeric(12, 2);
56	  v_product_id uuid;
57	  v_product record;
58	  v_line_gross numeric(12, 2);
59	  v_disc numeric(12, 2);
60	  v_disc_type text;
61	  v_item_disc numeric(12, 2);
62	  v_change numeric(12, 2);
63	  v_shift_id uuid;
64	  v_recipe record;
65	  v_table_id uuid;
66	  v_journal_lines jsonb;
67	begin
68	  if not private.owns_business(p_business_id) then
69	    raise exception 'not authorized';
70	  end if;
71	
72	  if p_client_ref is not null then
73	    select t.id, t.invoice_number into v_transaction_id, v_invoice_number
74	    from public.transactions t
75	    where t.business_id = p_business_id and t.client_ref = p_client_ref;
76	
77	    if found then
78	      return query select v_transaction_id, v_invoice_number, true;
79	      return;
80	    end if;
81	  end if;
82	
83	  if not exists (
84	    select 1 from public.cashiers c
85	    where c.id = p_cashier_id and c.business_id = p_business_id and c.active
86	  ) then
87	    raise exception 'invalid cashier';
88	  end if;
89	
90	  if p_customer_id is not null and not exists (
91	    select 1 from public.customers c
92	    where c.id = p_customer_id and c.business_id = p_business_id and c.deleted_at is null
93	  ) then
94	    raise exception 'invalid customer';
95	  end if;
96	
97	  if p_self_order_ids is not null and exists (
98	    select 1 from public.self_orders so
99	    where so.id = any(p_self_order_ids) and so.business_id <> p_business_id
100	  ) then
101	    raise exception 'invalid self order';
102	  end if;
103	
104	  if p_payment_method is null or length(trim(p_payment_method)) = 0 then
105	    raise exception 'payment method required';
106	  end if;
107	
108	  if p_items is null or jsonb_array_length(p_items) = 0 then
109	    raise exception 'cart is empty';
110	  end if;
111	
112	  if p_order_disc_type not in ('pct', 'amt') then
113	    raise exception 'invalid order discount type';
114	  end if;
115	
116	  if p_order_disc is null or p_order_disc < 0
117	     or (p_order_disc_type = 'pct' and p_order_disc > 100) then
118	    raise exception 'invalid order discount';
119	  end if;
120	
121	  select b.tax_enabled, b.tax_rate, b.service_enabled, b.service_rate
122	  into v_business
123	  from public.businesses b
124	  where b.id = p_business_id;
125	
126	  select id into v_shift_id
127	  from public.shifts
128	  where business_id = p_business_id and closed_at is null
129	  limit 1;
130	
131	  if v_shift_id is null then
132	    raise exception 'no active shift — open a shift before selling';
133	  end if;
134	
135	  if p_self_order_ids is not null and array_length(p_self_order_ids, 1) > 0 then
136	    select table_id into v_table_id
137	    from public.self_orders
138	    where id = p_self_order_ids[1];
139	  end if;
140	
141	  select count(*) + 1 into v_seq
142	  from public.transactions t
143	  where t.business_id = p_business_id
144	    and t.date::date = current_date;
145	
146	  v_invoice_number := 'INV-' || to_char(current_date, 'YYYYMMDD') || '-' || lpad(v_seq::text, 4, '0');
147	
148	  insert into public.transactions (
149	    business_id, shift_id, cashier_id, customer_id, table_id, invoice_number, date,
150	    subtotal_raw, subtotal, total, total_cost, gross_profit, client_ref
151	  ) values (
152	    p_business_id, v_shift_id, p_cashier_id, p_customer_id, v_table_id, v_invoice_number, now(),
153	    0, 0, 0, 0, 0, p_client_ref
154	  )
155	  returning id into v_transaction_id;
156	
157	  for v_item in select * from jsonb_array_elements(p_items)
158	  loop
159	    v_product_id := (v_item ->> 'product_id')::uuid;
160	    v_qty := (v_item ->> 'qty')::numeric;
161	    v_disc := coalesce((v_item ->> 'disc')::numeric, 0);
162	    v_disc_type := coalesce(v_item ->> 'disc_type', 'pct');
163	
164	    if v_qty is null or v_qty <= 0 then
165	      raise exception 'invalid quantity';
166	    end if;
167	
168	    if v_disc_type not in ('pct', 'amt') then
169	      raise exception 'invalid item discount type';
170	    end if;
171	
172	    if v_disc < 0 or (v_disc_type = 'pct' and v_disc > 100) then
173	      raise exception 'invalid item discount';
174	    end if;
175	
176	    select * into v_product
177	    from public.products p
178	    where p.id = v_product_id
179	      and p.business_id = p_business_id
180	      and p.deleted_at is null;
181	
182	    if not found then
183	      raise exception 'product not found: %', v_product_id;
184	    end if;
185	
186	    v_line_gross := v_product.price * v_qty;
187	    v_item_disc := case v_disc_type
188	      when 'pct' then round(v_line_gross * v_disc / 100)
189	      else least(v_disc * v_qty, v_line_gross)
190	    end;
191	
192	    insert into public.transaction_items (
193	      transaction_id, product_id, name, category, price, cost, qty, disc, disc_type
194	    ) values (
195	      v_transaction_id, v_product.id, v_product.name, v_product.category,
196	      v_product.price, v_product.cost, v_qty, v_disc, v_disc_type
197	    );
198	
199	    update public.products
200	    set stock = greatest(0, stock - v_qty)
201	    where id = v_product_id;
202	
203	    -- Consume ingredients per the product's recipe (if any).
204	    for v_recipe in
205	      select pr.ingredient_id, pr.qty as recipe_qty
206	      from public.product_recipes pr
207	      where pr.product_id = v_product_id and pr.ingredient_id is not null
208	    loop
209	      insert into public.transaction_ingredient_consumption (
210	        transaction_id, ingredient_id, qty
211	      ) values (
212	        v_transaction_id, v_recipe.ingredient_id, v_recipe.recipe_qty * v_qty
213	      );
214	
215	      update public.ingredients
216	      set stock = greatest(0, stock - (v_recipe.recipe_qty * v_qty))
217	      where id = v_recipe.ingredient_id;
218	    end loop;
219	
220	    v_subtotal_raw := v_subtotal_raw + v_line_gross;
221	    v_total_item_disc := v_total_item_disc + v_item_disc;
222	    v_total_cost := v_total_cost + v_product.cost * v_qty;
223	  end loop;
224	
225	  v_order_disc_amt := case p_order_disc_type
226	    when 'pct' then round((v_subtotal_raw - v_total_item_disc) * p_order_disc / 100)
227	    else least(p_order_disc, v_subtotal_raw - v_total_item_disc)
228	  end;
229	
230	  v_subtotal := v_subtotal_raw - v_total_item_disc - v_order_disc_amt;
231	
232	  if v_business.service_enabled then
233	    v_service := round(v_subtotal * v_business.service_rate / 100);
234	  end if;
235	
236	  if v_business.tax_enabled then
237	    v_tax := round((v_subtotal + v_service) * v_business.tax_rate / 100);
238	  end if;
239	
240	  v_total := v_subtotal + v_service + v_tax;
241	
242	  update public.transactions
243	  set subtotal_raw = v_subtotal_raw,
244	      subtotal = v_subtotal,
245	      total_item_disc = v_total_item_disc,
246	      order_disc_amt = v_order_disc_amt,
247	      service = v_service,
248	      tax = v_tax,
249	      total = v_total,
250	      total_cost = v_total_cost,
251	      gross_profit = v_subtotal - v_total_cost
252	  where id = v_transaction_id;
253	
254	  v_change := greatest(coalesce(p_received, v_total) - v_total, 0);
255	
256	  insert into public.transaction_payments (
257	    transaction_id, method, amount, received, change
258	  ) values (
259	    v_transaction_id, p_payment_method, v_total, p_received, v_change
260	  );
261	
262	  if p_self_order_ids is not null and array_length(p_self_order_ids, 1) > 0 then
263	    update public.self_orders
264	    set status = 'selesai'
265	    where id = any(p_self_order_ids)
266	      and business_id = p_business_id
267	      and status <> 'selesai';
268	  end if;
269	
270	  -- Auto-post the sale to the journal: Kas & Bank debited for the full total,
271	  -- but only (subtotal + service) — the business's actual earnings — is
272	  -- credited to Pendapatan Penjualan. PPN collected from the customer is
273	  -- credited to PPN Keluaran (a liability) instead, since it's held on
274	  -- behalf of the tax office, not revenue. Plus HPP / Persediaan
275	  -- independently whenever this sale had recipe-based cost data, even on a
276	  -- 100%-discount sale where v_total is 0 but stock was still consumed.
277	  v_journal_lines := '[]'::jsonb;
278	  if v_total > 0 then
279	    v_journal_lines := v_journal_lines || jsonb_build_array(
280	      jsonb_build_object('account_code', '1-001', 'debit', v_total, 'credit', 0),
281	      jsonb_build_object('account_code', '4-001', 'debit', 0, 'credit', v_subtotal + v_service)
282	    );
283	    if v_tax > 0 then
284	      v_journal_lines := v_journal_lines || jsonb_build_array(
285	        jsonb_build_object('account_code', '2-200', 'debit', 0, 'credit', v_tax)
286	      );
287	    end if;
288	  end if;
289	  if v_total_cost > 0 then
290	    v_journal_lines := v_journal_lines || jsonb_build_array(
291	      jsonb_build_object('account_code', '5-001', 'debit', v_total_cost, 'credit', 0),
292	      jsonb_build_object('account_code', '1-200', 'debit', 0, 'credit', v_total_cost)
293	    );
294	  end if;
295	  if jsonb_array_length(v_journal_lines) >= 2 then
296	    perform private.post_journal(
297	      p_business_id, now(), 'Penjualan ' || v_invoice_number, 'penjualan', v_transaction_id, v_journal_lines
298	    );
299	  end if;
300	
301	  return query select v_transaction_id, v_invoice_number, false;
302	end;
303	$$;
304	
305	grant execute on function public.checkout_transaction(
306	  uuid, uuid, jsonb, text, numeric, numeric, text, uuid, uuid[], uuid
307	) to authenticated;
308	
309	drop function if exists public.checkout_ticket_transaction(
310	  uuid, uuid, jsonb, text, numeric, uuid
311	);
312	
313	create or replace function public.checkout_ticket_transaction(
314	  p_business_id uuid,
315	  p_cashier_id uuid,
316	  p_items jsonb, -- array of {ticket_category_id, manual_numbers: string[]}
317	  p_payment_method text,
318	  p_received numeric default null,
319	  p_member_id uuid default null,
320	  p_client_ref uuid default null
321	)
322	returns table (transaction_id uuid, invoice_number text, already_existed boolean)
323	language plpgsql
324	security definer
325	set search_path = ''
326	as $$
327	declare
328	  v_business record;
329	  v_member record;
330	  v_invoice_number text;
331	  v_seq int;
332	  v_is_holiday boolean;
333	  v_subtotal numeric(12, 2) := 0;
334	  v_service numeric(12, 2) := 0;
335	  v_tax numeric(12, 2) := 0;
336	  v_total numeric(12, 2);
337	  v_change numeric(12, 2);
338	  v_transaction_id uuid;
339	  v_shift_id uuid;
340	  v_item jsonb;
341	  v_category_id uuid;
342	  v_category record;
343	  v_manual_numbers jsonb;
344	  v_manual_number text;
345	  v_use_member_price boolean := false;
346	  v_unit_price numeric(12, 2);
347	  v_qty int;
348	  v_serial int;
349	  v_journal_lines jsonb;
350	begin
351	  if not private.owns_business(p_business_id) then
352	    raise exception 'not authorized';
353	  end if;
354	
355	  if p_client_ref is not null then
356	    select t.id, t.invoice_number into v_transaction_id, v_invoice_number
357	    from public.ticket_transactions t
358	    where t.business_id = p_business_id and t.client_ref = p_client_ref;
359	
360	    if found then
361	      return query select v_transaction_id, v_invoice_number, true;
362	      return;
363	    end if;
364	  end if;
365	
366	  if not exists (
367	    select 1 from public.cashiers c
368	    where c.id = p_cashier_id and c.business_id = p_business_id and c.active
369	  ) then
370	    raise exception 'invalid cashier';
371	  end if;
372	
373	  if p_payment_method is null or length(trim(p_payment_method)) = 0 then
374	    raise exception 'payment method required';
375	  end if;
376	
377	  if p_items is null or jsonb_array_length(p_items) = 0 then
378	    raise exception 'cart is empty';
379	  end if;
380	
381	  select b.tax_enabled, b.tax_rate, b.service_enabled, b.service_rate
382	  into v_business
383	  from public.businesses b
384	  where b.id = p_business_id;
385	
386	  select id into v_shift_id
387	  from public.shifts
388	  where business_id = p_business_id and closed_at is null
389	  limit 1;
390	
391	  if v_shift_id is null then
392	    raise exception 'no active shift — open a shift before selling';
393	  end if;
394	
395	  if p_member_id is not null then
396	    select m.id, m.valid_from, m.valid_until
397	    into v_member
398	    from public.members m
399	    where m.id = p_member_id
400	      and m.business_id = p_business_id
401	      and m.deleted_at is null;
402	
403	    if not found then
404	      raise exception 'member not found';
405	    end if;
406	
407	    if current_date < v_member.valid_from or current_date > v_member.valid_until then
408	      raise exception 'membership tidak aktif (kadaluarsa atau belum berlaku)';
409	    end if;
410	
411	    v_use_member_price := true;
412	  end if;
413	
414	  v_is_holiday := extract(dow from current_date) in (0, 6)
415	    or exists (
416	      select 1 from public.ticket_holidays h
417	      where h.business_id = p_business_id and h.holiday_date = current_date
418	    );
419	
420	  select count(*) + 1 into v_seq
421	  from public.ticket_transactions t
422	  where t.business_id = p_business_id
423	    and t.date::date = current_date;
424	
425	  v_invoice_number := 'TIX-' || to_char(current_date, 'YYYYMMDD') || '-' || lpad(v_seq::text, 4, '0');
426	
427	  insert into public.ticket_transactions (
428	    business_id, shift_id, cashier_id, member_id, invoice_number, date,
429	    is_holiday, subtotal, service, tax, total, payment_method, received, change, client_ref
430	  ) values (
431	    p_business_id, v_shift_id, p_cashier_id, p_member_id, v_invoice_number, now(),
432	    v_is_holiday, 0, 0, 0, 0, p_payment_method, p_received, 0, p_client_ref
433	  )
434	  returning id into v_transaction_id;
435	
436	  for v_item in select * from jsonb_array_elements(p_items)
437	  loop
438	    v_category_id := (v_item ->> 'ticket_category_id')::uuid;
439	    v_manual_numbers := v_item -> 'manual_numbers';
440	
441	    if v_manual_numbers is null or jsonb_typeof(v_manual_numbers) <> 'array'
442	      or jsonb_array_length(v_manual_numbers) = 0 then
443	      raise exception 'manual ticket numbers required for category %', v_category_id;
444	    end if;
445	
446	    select * into v_category
447	    from public.ticket_categories
448	    where id = v_category_id
449	      and business_id = p_business_id
450	      and deleted_at is null
451	    for update;
452	
453	    if not found then
454	      raise exception 'ticket category not found: %', v_category_id;
455	    end if;
456	
457	    v_qty := jsonb_array_length(v_manual_numbers);
458	
459	    v_unit_price := case
460	      when v_use_member_price then v_category.member_price
461	      when v_category.group_min_qty > 0 and v_category.group_price is not null
462	        and v_qty >= v_category.group_min_qty then v_category.group_price
463	      when v_is_holiday then v_category.price_holiday
464	      else v_category.price_weekday
465	    end;
466	
467	    for v_manual_number in select jsonb_array_elements_text(v_manual_numbers)
468	    loop
469	      if v_manual_number is null or length(trim(v_manual_number)) = 0 then
470	        raise exception 'nomor tiket fisik tidak boleh kosong (kategori %)', v_category.name;
471	      end if;
472	
473	      v_serial := v_category.next_serial;
474	
475	      insert into public.ticket_serials (
476	        ticket_transaction_id, ticket_category_id, business_id,
477	        serial_no, manual_number, price, is_member_price
478	      ) values (
479	        v_transaction_id, v_category_id, p_business_id,
480	        v_serial, trim(v_manual_number), v_unit_price, v_use_member_price
481	      );
482	
483	      v_category.next_serial := v_category.next_serial + 1;
484	      v_subtotal := v_subtotal + v_unit_price;
485	    end loop;
486	
487	    update public.ticket_categories
488	    set next_serial = v_category.next_serial
489	    where id = v_category_id;
490	  end loop;
491	
492	  if v_business.service_enabled then
493	    v_service := round(v_subtotal * v_business.service_rate / 100);
494	  end if;
495	
496	  if v_business.tax_enabled then
497	    v_tax := round((v_subtotal + v_service) * v_business.tax_rate / 100);
498	  end if;
499	
500	  v_total := v_subtotal + v_service + v_tax;
501	  v_change := greatest(coalesce(p_received, v_total) - v_total, 0);
502	
503	  update public.ticket_transactions
504	  set subtotal = v_subtotal,
505	      service = v_service,
506	      tax = v_tax,
507	      total = v_total,
508	      change = v_change
509	  where id = v_transaction_id;
510	
511	  -- Revenue-only posting — no HPP/Persediaan lines exist for tickets.
512	  v_journal_lines := '[]'::jsonb;
513	  if v_total > 0 then
514	    v_journal_lines := v_journal_lines || jsonb_build_array(
515	      jsonb_build_object('account_code', '1-001', 'debit', v_total, 'credit', 0),
516	      jsonb_build_object('account_code', '4-002', 'debit', 0, 'credit', v_subtotal + v_service)
517	    );
518	    if v_tax > 0 then
519	      v_journal_lines := v_journal_lines || jsonb_build_array(
520	        jsonb_build_object('account_code', '2-200', 'debit', 0, 'credit', v_tax)
521	      );
522	    end if;
523	  end if;
524	  if jsonb_array_length(v_journal_lines) >= 2 then
525	    perform private.post_journal(
526	      p_business_id, now(), 'Penjualan Tiket ' || v_invoice_number, 'penjualan', v_transaction_id, v_journal_lines
527	    );
528	  end if;
529	
530	  return query select v_transaction_id, v_invoice_number, false;
531	end;
