11	  const totalCost = (items ?? []).reduce((sum, item) => {
12	    const ingredient = item.ingredients as unknown as { unit_cost: number } | null;
13	    return sum + Number(ingredient?.unit_cost ?? 0) * Number(item.qty);
14	  }, 0);
15	
16	  await supabase.from("products").update({ cost: totalCost }).eq("id", productId);
17	}
